import re
from collections import deque
from typing import List

TOKEN = re.compile(r"\d+|[A-Za-z_]\w*|[-+*/()]")
PREC = {"+": 1, "-": 1, "*": 2, "/": 2}

def apply(op, b, a):
    if op == "+": return a + b
    if op == "-": return a - b
    if op == "*": return a * b
    q = abs(a) // abs(b)              # truncate toward zero
    return q if (a >= 0) == (b >= 0) else -q

def evaluate(tokens, values):
    nums, ops = [], []
    def reduce_top():
        op = ops.pop()
        nums.append(apply(op, nums.pop(), nums.pop()))
    for tk in tokens:
        if tk.isdigit():
            nums.append(int(tk))
        elif tk == "(":
            ops.append(tk)
        elif tk == ")":
            while ops[-1] != "(":
                reduce_top()
            ops.pop()
        elif tk in PREC:
            while ops and ops[-1] != "(" and PREC[ops[-1]] >= PREC[tk]:
                reduce_top()
            ops.append(tk)
        else:
            nums.append(values[tk])
    while ops:
        reduce_top()
    return nums[0]

def evaluateExpressionMap(definitions: List[str]) -> List[str]:
    order, tokens = [], {}
    for d in definitions:
        name, expr = d.split("=", 1)
        name = name.strip()
        order.append(name)
        tokens[name] = TOKEN.findall(expr)

    indeg = {name: 0 for name in order}
    users = {name: [] for name in order}
    for name in order:
        deps = {tk for tk in tokens[name] if tk[0].isalpha() or tk[0] == "_"}
        for dep in deps:
            users[dep].append(name)
            indeg[name] += 1

    queue = deque(name for name in order if indeg[name] == 0)
    topo = []
    while queue:
        cur = queue.popleft()
        topo.append(cur)
        for nxt in users[cur]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                queue.append(nxt)
    if len(topo) < len(order):
        return ["CYCLE"]

    values = {}
    for name in topo:
        values[name] = evaluate(tokens[name], values)
    return [f"{name}={values[name]}" for name in order]
